import { readFile } from "node:fs/promises";
import { join } from "node:path";
import { ImageResponse } from "next/og";
import { clampTitle, DEFAULT_OG_TITLE } from "./title";

const CARD = {
  accent: "#53c9e8",
  accentSoft: "rgba(83, 201, 232, 0.4)",
  background: "#071e26",
  line: "rgba(244, 250, 252, 0.12)",
  muted: "#7a97a3",
  panel: "rgba(3, 13, 18, 0.45)",
  text: "#f4fafc",
};

// The brand mono, vendored under assets/ (OFL licensed, license alongside).
// Read once per instance; `process.cwd()` is the Next.js project directory.
let fontsPromise: Promise<{ bold: Buffer; regular: Buffer }> | null = null;

function loadFonts() {
  fontsPromise ??= Promise.all([
    readFile(join(process.cwd(), "assets/JetBrainsMono-Regular.ttf")),
    readFile(join(process.cwd(), "assets/JetBrainsMono-Bold.ttf")),
  ]).then(([regular, bold]) => ({ bold, regular }));
  return fontsPromise;
}

// The site's dot texture as a Satori-friendly tile: no filters or blend
// modes in this renderer, but a repeated inline-SVG background works.
const DOT_TILE = encodeURIComponent(
  "<svg xmlns='http://www.w3.org/2000/svg' width='24' height='24'><rect x='10' y='10' width='3' height='3' fill='rgb(244,250,252)' fill-opacity='0.14'/></svg>"
);

const SHORT_TITLE = 24;
const MEDIUM_TITLE = 46;

function titleSize(title: string): number {
  if (title.length <= SHORT_TITLE) {
    return 88;
  }
  if (title.length <= MEDIUM_TITLE) {
    return 72;
  }
  return 58;
}

/**
 * A PNG that doesn't exist until you ask for it. `ImageResponse` renders JSX
 * (flexbox only — Satori, not a browser) into an image at request time. The
 * card is drawn as a miniature of the site's live panels, in the site's own
 * mono. This same endpoint renders the page's real Open Graph image.
 */
export async function GET(request: Request): Promise<ImageResponse> {
  const { searchParams } = new URL(request.url);
  const title = clampTitle(searchParams.get("title"));
  const fonts = await loadFonts();

  // The site's own card already says the tagline up top — don't say it twice.
  const footer =
    title === DEFAULT_OG_TITLE
      ? "press the demos · read the source · new chapter every Monday"
      : "the playground for Next.js & Vercel — new chapter every Monday";

  return new ImageResponse(
    <div
      style={{
        backgroundColor: CARD.background,
        backgroundImage:
          "radial-gradient(1100px 700px at 10% -10%, rgba(83, 201, 232, 0.16), transparent 60%)",
        display: "flex",
        height: "100%",
        padding: 44,
        position: "relative",
        width: "100%",
      }}
    >
      <div
        style={{
          backgroundImage: `url("data:image/svg+xml,${DOT_TILE}")`,
          backgroundRepeat: "repeat",
          backgroundSize: "24px 24px",
          bottom: 0,
          display: "flex",
          left: 0,
          position: "absolute",
          right: 0,
          top: 0,
        }}
      />
      <div
        style={{
          backgroundColor: CARD.panel,
          border: `2px solid ${CARD.line}`,
          borderRadius: 28,
          display: "flex",
          flexDirection: "column",
          width: "100%",
        }}
      >
        <div
          style={{
            alignItems: "center",
            borderBottom: `2px solid ${CARD.line}`,
            display: "flex",
            justifyContent: "space-between",
            padding: "26px 40px",
          }}
        >
          <div style={{ alignItems: "center", display: "flex", gap: 16 }}>
            <div
              style={{
                backgroundColor: CARD.accent,
                borderRadius: 999,
                boxShadow: "0 0 22px rgba(83, 201, 232, 0.9)",
                display: "flex",
                height: 14,
                width: 14,
              }}
            />
            <div
              style={{
                color: CARD.muted,
                display: "flex",
                fontSize: 22,
                letterSpacing: 6,
              }}
            >
              LIVE
            </div>
          </div>
          <div style={{ color: CARD.muted, display: "flex", fontSize: 22 }}>
            hastoggle.dev
          </div>
        </div>

        <div
          style={{
            display: "flex",
            flex: 1,
            padding: "40px 56px",
          }}
        >
          <div
            style={{
              alignSelf: "center",
              color: CARD.text,
              display: "flex",
              fontSize: titleSize(title),
              fontWeight: 700,
              letterSpacing: -1,
              lineHeight: 1.15,
              maxWidth: 1000,
            }}
          >
            {title}
          </div>
        </div>

        <div
          style={{
            alignItems: "center",
            borderTop: `2px solid ${CARD.line}`,
            display: "flex",
            justifyContent: "space-between",
            padding: "24px 40px",
          }}
        >
          <div style={{ color: CARD.muted, display: "flex", fontSize: 22 }}>
            {footer}
          </div>
          <div
            style={{
              color: CARD.accentSoft,
              display: "flex",
              fontSize: 30,
              gap: 18,
            }}
          >
            <div style={{ display: "flex" }}>+</div>
            <div style={{ display: "flex" }}>+</div>
            <div style={{ display: "flex" }}>+</div>
          </div>
        </div>
      </div>
    </div>,
    {
      fonts: [
        {
          data: fonts.regular,
          name: "JetBrains Mono",
          style: "normal",
          weight: 400,
        },
        {
          data: fonts.bold,
          name: "JetBrains Mono",
          style: "normal",
          weight: 700,
        },
      ],
      // A card is a pure function of its title, so the CDN keeps it. Fresh
      // titles still render on demand; repeat unfurls of the same one don't.
      headers: {
        "Cache-Control":
          "public, max-age=3600, s-maxage=86400, stale-while-revalidate=604800",
      },
      height: 630,
      width: 1200,
    }
  );
}
import { keys as analytics } from "@repo/analytics/keys";
import {
  type NoseconeOptions,
  nosecone,
  withVercelToolbar,
} from "@repo/security/middleware";

const isDevelopment = process.env.NODE_ENV === "development";

/**
 * PostHog talks to its API host directly (the `/ingest` rewrite in
 * next-config points at the US region and is not what the SDK is configured
 * with) and pulls its remote config and lazy modules from the matching
 * assets host — `eu.i.posthog.com` pairs with `eu-assets.i.posthog.com`,
 * the same substitution the SDK makes itself.
 */
type HttpsOrigin = `https://${string}.${string}`;

const HTTPS_ORIGIN = /^https:\/\/[^/]+\.[^/]+$/;

const isHttpsOrigin = (value: string): value is HttpsOrigin =>
  HTTPS_ORIGIN.test(value);

export function posthogOrigins(apiHost: string): HttpsOrigin[] {
  const { origin, hostname } = new URL(apiHost);
  const assets = origin.replace(
    hostname,
    hostname.replace(".i.", "-assets.i.")
  );
  const origins = assets === origin ? [origin] : [origin, assets];
  return origins.filter(isHttpsOrigin);
}

const posthog = posthogOrigins(analytics().NEXT_PUBLIC_POSTHOG_HOST);

/**
 * The site's Content Security Policy, written out in full rather than
 * derived from nosecone's Next.js defaults. Those defaults mint a nonce per
 * request, and a nonce only reaches scripts on dynamically rendered pages —
 * this site prerenders its shells with Cache Components, so a nonce would
 * leave every inline bootstrap script blocked. `'unsafe-inline'` is the
 * price of a static shell; the policy still pins script origins, forbids
 * framing and plugins, and keeps forms and `<base>` on this origin.
 *
 * Third parties that need an allowance:
 * - Google Analytics via `@next/third-parties` (script, beacon, pixel).
 * - PostHog's API and assets hosts, derived from the configured host.
 * - `picsum.photos`, the one remote image host in next.config.
 * Sentry goes through the `/monitoring` tunnel and Vercel Analytics through
 * `/_vercel`, so both are same-origin. The Vercel toolbar (preview and local
 * only) is widened in by `withVercelToolbar` where it renders.
 */
const directives: Extract<
  NoseconeOptions["contentSecurityPolicy"],
  object
>["directives"] = {
  baseUri: ["'none'"],
  childSrc: ["'none'"],
  connectSrc: [
    "'self'",
    ...posthog,
    "https://*.google-analytics.com",
    "https://*.analytics.google.com",
    "https://*.googletagmanager.com",
  ] as const,
  defaultSrc: ["'self'"],
  fontSrc: ["'self'"],
  formAction: ["'self'"],
  frameAncestors: ["'none'"],
  frameSrc: ["'none'"],
  imgSrc: [
    "'self'",
    "blob:",
    "data:",
    "https://picsum.photos",
    "https://*.google-analytics.com",
    "https://*.googletagmanager.com",
  ],
  manifestSrc: ["'self'"],
  mediaSrc: ["'self'"],
  objectSrc: ["'none'"],
  scriptSrc: [
    "'self'",
    "'unsafe-inline'",
    ...posthog,
    "https://*.googletagmanager.com",
    // Turbopack's dev runtime evaluates source maps and HMR updates.
    ...(isDevelopment ? ["'unsafe-eval'" as const] : []),
  ] as const,
  styleSrc: ["'self'", "'unsafe-inline'"],
  workerSrc: ["'self'", "blob:"],
};

export const securityOptions: NoseconeOptions = {
  contentSecurityPolicy: { directives },
  // `require-corp` would refuse the analytics script and any remote image
  // that does not send Cross-Origin-Resource-Policy; nothing here needs
  // the cross-origin isolation it buys.
  crossOriginEmbedderPolicy: false,
  crossOriginOpenerPolicy: { policy: "same-origin" },
  crossOriginResourcePolicy: { policy: "same-origin" },
  originAgentCluster: true,
  // Outbound links (GitHub, the Next.js docs) get the origin, never the path.
  referrerPolicy: { policy: ["strict-origin-when-cross-origin"] },
  strictTransportSecurity: {
    includeSubDomains: true,
    maxAge: 63_072_000,
    preload: false,
  },
  xContentTypeOptions: true,
  xDnsPrefetchControl: { allow: false },
  xDownloadOptions: true,
  xFrameOptions: { action: "deny" },
  xPermittedCrossDomainPolicies: { permittedPolicies: "none" },
  xXssProtection: true,
};

export const securityOptionsWithToolbar: NoseconeOptions =
  withVercelToolbar(securityOptions);

/**
 * Copies every security header onto `response`, whatever produced it. The
 * proxy chain (i18n rewrite, Arcjet) always returns a response of its own,
 * so the headers have to be merged in rather than returned as an alternative.
 */
export function withSecurityHeaders<T extends Response>(
  response: T,
  headers: Headers
): T {
  headers.forEach((value, key) => {
    response.headers.set(key, value);
  });
  return response;
}

export const securityHeaders = (options: NoseconeOptions): Headers =>
  nosecone(options);

