  SIMPLE_IDLE_CAPTION,
  SIMPLE_CYCLED_CAPTION,
  MACHINERY_IDLE_CAPTION,
  EXPIRED_CAPTION,
  REVEALED_CAPTION,
  REBAKE_FAILED_CAPTION,
  SETTLING_READOUT.caption,
];

