import { Switch } from "@repo/design-system/components/ui/switch";

interface ViewSwitchProps {
  checked: boolean;
  disabled?: boolean;
  id: string;
  label: string;
  onCheckedChange: (checked: boolean) => void;
}

/**
 * The instrument's view control: one labelled switch in the chrome corner
 * every editor keeps its view toggles in (design.md §1). Panels differ in
 * what the switch means — slow motion, request view — never in how it
 * looks.
 */
export function ViewSwitch({
  checked,
  disabled,
  id,
  label,
  onCheckedChange,
}: ViewSwitchProps) {
  return (
    <div className="flex items-center gap-2.5">
      <label
        className="cursor-pointer select-none font-mono font-semibold text-[0.7rem] text-muted-foreground uppercase tracking-[0.2em]"
        htmlFor={id}
      >
        {label}
      </label>
      <Switch
        checked={checked}
        disabled={disabled}
        id={id}
        onCheckedChange={onCheckedChange}
      />
    </div>
  );
}
''')

open(P+'stable-stack.tsx','w').write('''import { cn } from "@repo/design-system/lib/utils";
import type { ReactNode } from "react";

type Variant = string | { key: string; node: ReactNode };

interface StableStackProps extends React.ComponentPropsWithoutRef<"div"> {
  /** The variant on show; every other one is a ghost. */
  active?: string;
  as?: "div" | "p" | "span";
  /**
   * Shown instead of any variant, with every variant a ghost — for text
   * whose live form differs from its reserved one (a real clock against
   * a placeholder), where only the size has to match.
   */
  value?: ReactNode;
  /** Everything the cell could show. A string is its own key and node. */
  variants: readonly Variant[];
}

/**
 * Renders what a cell shows stacked on top of everything it could show, so
 * the cell is always as tall and as wide as its worst case and nothing
 * below it moves when the content changes. Reserving by hand means a
 * magic number per breakpoint that a copy edit silently invalidates; this
 * reserves the real thing, at whatever width the reader happens to be.
 *
 * The ghosts are `visibility: hidden`, so they take space but leave the
 * tab order, the selection, and — with `aria-hidden` — the announcement
 * alone.
 */
export function StableStack({
  active,
  as: Element = "span",
  className,
  value,
  variants,
  ...props
}: StableStackProps) {
  const showsValue = value !== undefined;
  return (
    <Element {...props} className={cn("grid", className)}>
      {variants.map((variant) => {
        const { key, node } =
          typeof variant === "string"
            ? { key: variant, node: variant }
            : variant;
        const shown = !showsValue && key === active;
        return (
          <span
            aria-hidden={!shown}
            className={cn("[grid-area:1/1]", !shown && "invisible")}
            key={key}
          >
            {node}
          </span>
        );
      })}
      {showsValue ? <span className="[grid-area:1/1]">{value}</span> : null}
    </Element>
  );
}
''')

open(P+'locked-look.ts','w').write('''import { cn } from "@repo/design-system/lib/utils";

/**
 * The outline variant's `disabled:` look, re-expressed for `aria-disabled` —
 * a locked deck step stays a real, focusable element, so keyboard and
 * screen-reader users don't lose their place when its lock state flips.
 * See MarketingButton's `outline` variant.
 *
 * The hover override earns its place: a natively disabled button is
 * excluded from `:hover` matching, but an `aria-disabled` one is still
 * live, so the variant's `hover:bg-muted` would light up a button that
 * does nothing.
 */
export const LOCKED_LOOK = cn(
  "aria-disabled:bg-transparent aria-disabled:opacity-40",
  "aria-disabled:cursor-not-allowed aria-disabled:hover:bg-transparent"
);
''')

def edit(path, pairs):
    s=open(path).read()
    for old,new in pairs:
        assert old in s, (path, old[:60])
        s=s.replace(old,new)
    open(path,'w').write(s)

